// Probe 2: latched strip-all session, transcript carries an orphan image
// tool result, provider always 413s. Diagnose why the ladder stands down.
import 'package:flutter_agent_harness/flutter_agent_harness.dart';

const tooLarge = 'error: 413: Request Entity Too Large';

void main() async {
  var savedConfig = imageRegistryConfig;
  imageRegistryConfig = const ImageRegistryConfig();
  final recovery = ImagePayloadRecoveryState()
    ..halveBudget(8 * 1024 * 1024)
    ..halveBudget(8 * 1024 * 1024)
    ..stripAll = true;

  var sends = 0;
  AssistantMessageEventStream streamFn(
    Model model,
    Context context, {
    CancelToken? cancelToken,
  }) {
    sends++;
    final stream = AssistantMessageEventStream();
    final msg = AssistantMessage(
      content: const [],
      api: 'test-api',
      provider: 'copilot',
      model: 'vision',
      usage: Usage.zero,
      stopReason: StopReason.error,
      errorMessage: tooLarge,
      timestamp: DateTime.utc(2026),
    );
    stream
      ..push(StartEvent(partial: msg))
      ..push(ErrorEvent(reason: StopReason.error, error: msg));
    stream.end();
    return stream;
  }

  final history = [
    AssistantMessage(
      content: [
        ToolCall(id: 'c0', name: 'read', arguments: {'path': '/tmp/i.png'}),
      ],
      api: 'test-api',
      provider: 'copilot',
      model: 'vision',
      usage: Usage.zero,
      stopReason: StopReason.toolUse,
      timestamp: DateTime.utc(2026),
    ),
    ToolResultMessage(
      toolCallId: 'c0',
      toolName: 'read',
      content: [ImageContent(data: 'x' * 3000000, mimeType: 'image/png')],
      isError: false,
      timestamp: DateTime.utc(2026),
    ),
  ];
  final events = <AgentEvent>[];
  final messages = await runAgentLoop(
    prompts: [UserMessage.text('continue')],
    context: Context(messages: history),
    config: AgentLoopConfig(
      model: Model(
        id: 'vision',
        api: 'test-api',
        provider: 'copilot',
        baseUrl: 'https://x',
        input: const ['text'],
        contextWindow: 100000,
        maxTokens: 4096,
      ),
      imageRecovery: recovery,
    ),
    streamFunction: streamFn,
    toolExecutor: (_, _, _) async => const ToolExecutionResult(content: []),
    emit: events.add,
  );
  final last = messages.whereType<AssistantMessage>().last;
  print('final stop=${last.stopReason} err=${last.errorMessage}');
  print('classified=${isPayloadTooLargeError(last.errorMessage)}');
  print('TOTAL SENDS: $sends');
  print('loop recovery events: ${events.whereType<ImagePayloadRecoveryEvent>().length}');
  imageRegistryConfig = savedConfig;
}

