      timestamp: DateTime.utc(2026)),
  ];
  ImageDropReport? report;
  rewriteHistoryImages(window, stripAll: true, onReport: (r) => report = r);
  final view = ImageDropUx().observe(report!)!;
  print('P3 prominent=${view.prominent} line=${view.line}');
}
EOF
